candidates.raw:
/* 1. Input Validation */
int valid_input = 1;
if (!wo_input.enable) {
    valid_input = 0;
} else if (wo_input.wheel_count != 4) {
    valid_input = 0;
} else if (wo_input.wheels == NULL) {
    valid_input = 0;
} else {
    if (!(wo_config.release_rad_s >= 0.0 && 
          wo_config.release_rad_s < wo_config.warn_rad_s && 
          wo_config.warn_rad_s < wo_config.trip_rad_s)) {
        valid_input = 0;
    }
    else if (!isfinite(wo_config.derate_torque_nm) || wo_config.derate_torque_nm <= 0.0 ||
             !isfinite(wo_config.brake_torque_nm) || wo_config.brake_torque_nm <= 0.0) {
        valid_input = 0;
    }
    else if (!isfinite(wo_config.torque_slew_nm_per_cycle) || wo_config.torque_slew_nm_per_cycle <= 0.0 ||
             !isfinite(wo_config.dt_s) || wo_config.dt_s <= 0.0) {
        valid_input = 0;
    }
    else if (wo_config.release_cycles < 1 || wo_config.release_cycles > 100 ||
             wo_config.minimum_brake_cycles < 1 || wo_config.minimum_brake_cycles > 100 ||
             wo_config.cooldown_cycles < 1 || wo_config.cooldown_cycles > 100) {
        valid_input = 0;
    }
    else if (wo_config.brake_torque_nm < wo_config.derate_torque_nm) {
        valid_input = 0;
    }

    if (valid_input) {
        for (size_t i = 0; i < 4; ++i) {
            if (!isfinite(wo_input.wheels[i].speed_rad_s) ||
                !adcs_is_finite_vec3(&wo_input.wheels[i].axis_body)) {
                valid_input = 0;
                break;
            }
        }
    }
}

/* Initialize output */
wo_output.mode = WO_NORMAL;
wo_output.clean = 0;
wo_output.elapsed = 0;
wo_output.limited_mask = 0;
for (int i = 0; i < 4; ++i) {
    wo_output.wheel_torque_nm[i] = 0.0;
}
wo_output.maximum_speed_rad_s = 0.0;
wo_output.brake_power_w = 0.0;
wo_output.dissipated_energy_j = 0.0;
wo_output.momentum_nms.x = 0.0;
wo_output.momentum_nms.y = 0.0;
wo_output.momentum_nms.z = 0.0;
wo_output.momentum_norm_nms = 0.0;

if (!valid_input) {
    wo_output.mode = WO_FAULT;
    return;
}

/* 2. Cluster Momentum */
adcs_vec3_t momentum_nms;
adcs_status_t mom_status = adcs_wheel_momentum(wo_input.wheels, 4, &momentum_nms);
if (mom_status != ADCS_OK || !isfinite(momentum_nms.x) || !isfinite(momentum_nms.y) || !isfinite(momentum_nms.z)) {
    wo_output.mode = WO_FAULT;
    return;
}

double momentum_norm = sqrt(momentum_nms.x*momentum_nms.x + momentum_nms.y*momentum_nms.y + momentum_nms.z*momentum_nms.z);
if (!isfinite(momentum_norm)) {
    wo_output.mode = WO_FAULT;
    return;
}

/* 3. Speed Analysis */
double max_abs_speed = 0.0;
double speeds[4];
for (int i = 0; i < 4; ++i) {
    speeds[i] = wo_input.wheels[i].speed_rad_s;
    double abs_spd = fabs(speeds[i]);
    if (abs_spd > max_abs_speed) {
        max_abs_speed = abs_spd;
    }
}

/* 4. State Machine Transitions */
wo_mode_t next_mode = wo_state.mode;

if (wo_state.mode == WO_NORMAL) {
    if (max_abs_speed >= wo_config.trip_rad_s) {
        next_mode = WO_BRAKE;
        wo_state.elapsed = 0;
        wo_state.clean = 0;
    } else if (max_abs_speed >= wo_config.warn_rad_s) {
        next_mode = WO_DERATE;
        wo_state.elapsed = 0;
        wo_state.clean = 0;
    }
} else if (wo_state.mode == WO_DERATE) {
    if (max_abs_speed >= wo_config.trip_rad_s) {
        next_mode = WO_BRAKE;
        wo_state.elapsed = 0;
        wo_state.clean = 0;
    } else {
        if (max_abs_speed <= wo_config.release_rad_s) {
            wo_state.clean++;
        } else {
            wo_state.clean = 0;
        }
        if (wo_state.clean >= wo_config.release_cycles) {
            next_mode = WO_NORMAL;
            wo_state.elapsed = 0;
            wo_state.clean = 0;
        }
    }
} else if (wo_state.mode == WO_BRAKE) {
    if (max_abs_speed >= wo_config.trip_rad_s) {
        next_mode = WO_BRAKE;
        // Remains in BRAKE, do not reset elapsed
    } else {
        wo_state.elapsed++;
        if (wo_state.elapsed >= wo_config.minimum_brake_cycles) {
            if (max_abs_speed <= wo_config.release_rad_s) {
                wo_state.clean++;
            } else {
                wo_state.clean = 0;
            }
            if (wo_state.clean >= wo_config.release_cycles) {
                next_mode = WO_COOLDOWN;
                wo_state.elapsed = 0;
                wo_state.clean = 0;
            }
        }
    }
} else if (wo_state.mode == WO_COOLDOWN) {
    wo_state.elapsed++;
    if (max_abs_speed >= wo_config.trip_rad_s) {
        next_mode = WO_BRAKE;
        wo_state.elapsed = 0;
        wo_state.clean = 0;
    } else if (wo_state.elapsed >= wo_config.cooldown_cycles) {
        next_mode = WO_NORMAL;
        wo_state.elapsed = 0;
        wo_state.clean = 0;
    }
}

wo_state.mode = next_mode;

/* 5. Torque Calculation with Slew Limit */
double total_power = 0.0;
double limited_torques[4] = {0};
unint32 mask = 0;

for (int i = 0; i < 4; ++i) {
    double target_torque = 0.0;
    double speed = speeds[i];
    double abs_speed = fabs(speed);

    if (next_mode == WO_DERATE) {
        if (abs_speed > wo_config.release_rad_s) {
            double excess = abs_speed - wo_config.release_rad_s;
            double denom = wo_config.trip_rad_s - wo_config.release_rad_s;
            double ratio = excess / denom;
            double raw = wo_config.derate_torque_nm * ratio;
            if (raw > wo_config.derate_torque_nm) raw = wo_config.derate_torque_nm;
            target_torque = copysign(raw, -speed);
        }
    } else if (next_mode == WO_BRAKE) {
        if (abs_speed > FLT64_ZERO) {
            target_torque = copysign(wo_config.brake_torque_nm, -speed);
        }
    }
    // NORMAL and COOLDOWN target 0.0

    /* Slew Limit */
    double prev = wo_state.previous_wheel_torque_nm[i];
    double slew = wo_config.torque_slew_nm_per_cycle;
    double diff = target_torque - prev;

    if (diff > slew) {
        limited_torques[i] = prev + slew;
    } else if (diff < -slew) {
        limited_torques[i] = prev - slew;
    } else {
        limited_torques[i] = target_torque;
    }

    /* Power & Mask */
    total_power += fabs(limited_torques[i] * speed);
    if (fabs(limited_torques[i]) > FLT64_ZERO) {
        mask |= (1U << i);
    }
}

/* Update Persistent State */
wo_state.dissipated_energy_j += total_power * wo_config.dt_s;
wo_state.previous_wheel_torque_nm[0] = limited_torques[0];
wo_state.previous_wheel_torque_nm[1] = limited_torques[1];
wo_state.previous_wheel_torque_nm[2] = limited_torques[2];
wo_state.previous_wheel_torque_nm[3] = limited_torques[3];

/* Fill Output */
wo_output.mode = next_mode;
wo_output.clean = wo_state.clean;
wo_output.elapsed = wo_state.elapsed;
wo_output.limited_mask = mask;
for (int i = 0; i < 4; ++i) {
    wo_output.wheel_torque_nm[i] = limited_torques[i];
}
wo_output.maximum_speed_rad_s = max_abs_speed;
wo_output.brake_power_w = total_power;
wo_output.dissipated_energy_j = wo_state.dissipated_energy_j;
wo_output.momentum_nms = momentum_nms;
wo_output.momentum_norm_nms = momentum_norm;

